const CHANGE_ITEM_DISPLAY_LABELS={weakening_nullify:'弱化効果無効',weakening_avoid:'弱化効果回避',weakening_remove:'弱化効果解除',status_nullify:'状態変化無効',status_remove:'状態変化解除',severance_counter:'分断対策',isolation_counter:'絶縁対策',chain_nullify_counter:'連鎖無効対策',control_counter:'制御対策',buff_protection:'強化解除・奪取対策',critical_rate_up:'会心発生',critical_power_up:'会心威力',critical_tactic_rate_up:'撃心発生',critical_tactic_power_up:'撃心威力',attack_speed_up:'攻撃速度',tactic_speed:'戦法速度',tactic_gauge:'戦法ゲージ',wounded_recovery:'負傷兵回復',wounded_survival:'負傷兵生存',healing:'兵力回復'};
